<script>
    const serviceConfig = {
        hours: "Mon-Fri: 8am - 8pm",
        helpCentreUrl: "https://help.maplesure.com"
    };

    const mockMemberData = {
        "123456": "John Doe",
        "987654": "Jane Smith"
    };

    function lookupMember() {
        const memberId = document.getElementById('member-id').value;
        const memberDetails = document.getElementById('member-details');
        if (mockMemberData[memberId]) {
            memberDetails.innerHTML = `<strong>Member Name:</strong> ${mockMemberData[memberId]}`;
        } else {
            memberDetails.innerHTML = "Member not found.";
        }
    }

    function submitForm() {
        const confirmation = document.getElementById('confirmation');
        const claimForm = document.getElementById('claim-form');
        const referenceNumber = generateReferenceNumber();
        document.getElementById('reference-number').textContent = referenceNumber;
        claimForm.style.display = 'none';
        confirmation.style.display = 'block';
    }

    function generateReferenceNumber() {
        const date = new Date();
        return `MS-${date.getFullYear()}-${('0' + (date.getMonth() + 1)).slice(-2)}-XXXX`;
    }

    document.getElementById('documents').addEventListener('change', function() {
        const fileList = document.getElementById('file-list');
        fileList.innerHTML = '';
        Array.from(this.files).forEach(file => {
            const li = document.createElement('li');
            li.textContent = file.name;
            fileList.appendChild(li);
        });
    });
</script>

